import type { FileStorage } from './index'

/** `<id>/<uuid>`: both parts are generated by the server, never taken from a client. */
const KEY = /^[a-f\d]{24}\/[a-f\d-]{36}$/

/** The part of MongoDB's GridFSBucket this uses (so a test can stand in for it). */
export interface BucketLike {
  openUploadStream(filename: string): NodeJS.WritableStream
  openDownloadStreamByName(filename: string): NodeJS.ReadableStream
  find(filter: { filename: string }): { toArray(): Promise<{ _id: unknown }[]> }
  delete(id: unknown): Promise<void>
}

/**
 * File storage in the same MongoDB the app already uses (GridFS): no extra
 * service, package or environment variable. Files are split into chunks, so
 * there is no 16 MB document limit, and they are kept apart from the app's own
 * collections in `<bucket>.files` / `<bucket>.chunks`.
 *
 * It is what production uses (a serverless host has no disk that lasts). The
 * file-size limit there is lower than in development, because the host caps a
 * request body (see MAX_ATTACHMENT_BYTES in lib/attachments).
 */
export class GridFsFileStorage implements FileStorage {
  readonly name = 'mongodb-gridfs'

  constructor(
    private readonly bucketName = 'files',
    private readonly getBucket: () => Promise<BucketLike> = async () => {
      // Loaded only when a file is actually stored or read: importing this module must not need the database settings.
      const { connectToDatabase } = await import('@/lib/db/mongodb')
      const conn = await connectToDatabase()
      return new conn.mongo.GridFSBucket(conn.connection.db!, { bucketName: this.bucketName }) as unknown as BucketLike
    }
  ) {}

  private check(key: string) {
    if (!KEY.test(key)) throw new Error('Invalid storage key')
  }

  async put(key: string, data: Buffer): Promise<void> {
    this.check(key)
    const bucket = await this.getBucket()
    await new Promise<void>((resolve, reject) => {
      const upload = bucket.openUploadStream(key)
      upload.once('error', reject)
      upload.once('finish', () => resolve())
      upload.end(data)
    })
  }

  async get(key: string): Promise<Buffer | null> {
    this.check(key)
    const bucket = await this.getBucket()
    if ((await bucket.find({ filename: key }).toArray()).length === 0) return null

    const chunks: Buffer[] = []
    await new Promise<void>((resolve, reject) => {
      const download = bucket.openDownloadStreamByName(key)
      download.on('data', (chunk: Buffer) => chunks.push(Buffer.from(chunk)))
      download.once('error', reject)
      download.once('end', () => resolve())
    })
    return Buffer.concat(chunks)
  }

  async delete(key: string): Promise<void> {
    this.check(key)
    const bucket = await this.getBucket()
    for (const file of await bucket.find({ filename: key }).toArray()) {
      try {
        await bucket.delete(file._id)
      } catch (error) {
        // Already gone (a repeated delete) is not an error.
        if (!/FileNotFound/i.test(String((error as Error)?.name ?? '') + String((error as Error)?.message ?? ''))) throw error
      }
    }
  }
}

